update ai_skill_component
   set enabled = #{enabled}, revision = revision + 1, updated_at = now()
 where id = #{id}

update ai_skill_component
   set revision = revision + 1, updated_at = now()
 where id = #{id} and revision = #{expectedRevision}

mapper.select:
select id, skill_id, relative_path, content, content_digest, updated_at
  from ai_skill_draft_file
 where skill_id = #{skillId} and relative_path = #{path}

mapper.update:
update ai_skill_component
   set draft_revision = draft_revision + 1, updated_at = now()
 where id = #{skillId}

mapper.select:
select 
  from ai_skill_release r join ai_skill_component c on c.id = r.skill_id
 where r.id = #{id}

select 
  from ai_skill_release r join ai_skill_component c on c.id = r.skill_id
 where c.component_key = #{key} and r.version = #{version}

mapper.update:
update ai_skill_release
   set state = #{state}
 where id = #{releaseId} and state in ('STAGED', 'ACTIVE')

update ai_skill_component c
   set published_version = #{version},
       publication_generation = #{expectedGeneration},
       revision = revision + 1,
       updated_at = now()
 where c.id = #{skillId}
   and publication_generation < #{expectedGeneration}
   and exists (
       select 1
         from ai_skill_release r
        where r.skill_id = c.id
          and r.version = #{version}
          and r.generation = #{expectedGeneration}
          and r.state = 'ACTIVE'
   )

mapper.select:
select count(*)
  from ai_skill_component
 where id = #{skillId}
   and published_version = #{version}
   and publication_generation = #{expectedGeneration}
